  const raw = items[id], n = raw === true ? 1 : typeof raw === 'number' ? raw : typeof raw === 'string' && /^[0-9]+$/.test(raw) ? Number(raw) : 0;
  return Number.isSafeInteger(n) && n > 0 ? n : 0;
}
